9 | export interface ToolResultLike {
10 | 	content: Array<{ type: string; text?: string }>;
11 | 	details?: unknown;
12 | 	isError?: boolean;
13 | }
14 | 
15 | export interface ExplorationLine {
16 | 	verb: "Read" | "Search" | "List";
17 | 	target: string;
18 | }
