20 | function stringArg(args: unknown, key: string): string | undefined {
21 | 	if (!args || typeof args !== "object" || !(key in args)) return undefined;
22 | 	const value = (args as Record<string, unknown>)[key];
23 | 	return typeof value === "string" && value.trim() ? value : undefined;
24 | }
25 | 
26 | const READ_COMMANDS = new Set(["cat", "head", "tail", "wc", "nl", "file", "stat"]);
27 | const SEARCH_COMMANDS = new Set(["rg", "grep", "egrep", "fgrep", "ag", "find", "fd"]);
28 | const LIST_COMMANDS = new Set(["ls", "tree", "pwd"]);
29 | const READ_GIT_SUBCOMMANDS = new Set(["status", "log", "diff", "show", "blame"]);
30 | 
31 | /**
32 |  * Classify a shell command as reading, searching, or listing when every part of it
33 |  * is a known read-only command. Anything with redirection, substitution, in-place
34 |  * edits, or an unknown program is a plain shell command. Display only; never a policy check.
35 |  */
36 | export function classifyShellCommand(command: string): "read" | "search" | "list" | "shell" {
37 | 	if (/[>\x60]|\$\(|<\(/.test(command)) return "shell";
38 | 	const kinds = new Set<"read" | "search" | "list">();
39 | 	for (const part of command.split(/&&|\|\||[;|\n]/)) {
40 | 		const words = part.trim().split(/\s+/).filter(Boolean);
41 | 		const program = words[0];
42 | 		if (!program) continue;
43 | 		if (program === "cd") continue;
44 | 		if (READ_COMMANDS.has(program)) kinds.add("read");
45 | 		else if (program === "sed" && words.includes("-n") && !words.some((word) => word.startsWith("-i")))
46 | 			kinds.add("read");
47 | 		else if (program === "git" && READ_GIT_SUBCOMMANDS.has(words[1] ?? "")) kinds.add("read");
48 | 		else if (SEARCH_COMMANDS.has(program) && !words.some((word) => word === "-exec" || word === "-delete"))
49 | 			kinds.add("search");
50 | 		else if (LIST_COMMANDS.has(program)) kinds.add("list");
51 | 		else return "shell";
52 | 	}
53 | 	if (kinds.has("search")) return "search";
54 | 	if (kinds.has("read")) return "read";
55 | 	if (kinds.has("list")) return "list";
56 | 	return "shell";
57 | }
58 | 
59 | /**
60 |  * Read, search, or list description for an exploration call; undefined for
61 |  * anything else (mutations, non-read-only shell commands, other tools), which
62 |  * renders as its own row.
63 |  */
64 | export function describeExploration(name: string, args: unknown): ExplorationLine | undefined {
65 | 	const path = stringArg(args, "path");
66 | 	switch (name) {
67 | 		case "read": {
68 | 			const offset = args && typeof args === "object" && "offset" in args ? args.offset : undefined;
69 | 			const limit = args && typeof args === "object" && "limit" in args ? args.limit : undefined;
70 | 			const range =
71 | 				typeof offset === "number"
72 | 					? `:${offset}${typeof limit === "number" ? `-${offset + limit - 1}` : ""}`
73 | 					: typeof limit === "number"
74 | 						? `:1-${limit}`
75 | 						: "";
76 | 			return { verb: "Read", target: `${path ?? "file"}${range}` };
77 | 		}
78 | 		case "grep":
79 | 		case "find": {
80 | 			const pattern = stringArg(args, "pattern") ?? "";
81 | 			return { verb: "Search", target: path ? `${pattern} in ${path}` : pattern };
82 | 		}
83 | 		case "ls":
84 | 			return { verb: "List", target: path ?? "." };
85 | 		case "bash": {
86 | 			const command = stringArg(args, "command");
87 | 			if (!command) return undefined;
88 | 			const kind = classifyShellCommand(command);
89 | 			if (kind === "shell") return undefined;
90 | 			const target = command.trim().split("\n", 1)[0] ?? "";
91 | 			return { verb: kind === "read" ? "Read" : kind === "search" ? "Search" : "List", target };
92 | 		}
93 | 		default:
94 | 			return undefined;
95 | 	}
96 | }
