98 | function textOf(result: ToolResultLike): string {
99 | 	return result.content
100 | 		.filter((block) => block.type === "text")
101 | 		.map((block) => block.text ?? "")
102 | 		.join("\n")
103 | 		.replace(/\r/g, "")
104 | 		.trimEnd();
105 | }
106 | 
107 | export function resultTextLines(result: ToolResultLike | undefined): string[] {
108 | 	if (!result) return [];
109 | 	const text = textOf(result);
110 | 	return text ? text.split("\n") : [];
111 | }
