113 | function diffStats(details: unknown): string | undefined {
114 | 	if (!details || typeof details !== "object" || !("diff" in details) || typeof details.diff !== "string") {
115 | 		return undefined;
116 | 	}
117 | 	let added = 0;
118 | 	let removed = 0;
119 | 	for (const line of details.diff.split("\n")) {
120 | 		if (line.startsWith("+")) added++;
121 | 		else if (line.startsWith("-")) removed++;
122 | 	}
123 | 	return `+${added} -${removed}`;
124 | }
