126 | /** One-line outcome for a finished, collapsed tool row. */
127 | export function summarizeToolResult(name: string, result: ToolResultLike): string {
128 | 	const details = result.details;
129 | 	if (
130 | 		details &&
131 | 		typeof details === "object" &&
132 | 		"backgroundTaskId" in details &&
133 | 		typeof details.backgroundTaskId === "string"
134 | 	) {
135 | 		const started = "backgroundOrigin" in details && details.backgroundOrigin === "model";
136 | 		return `${started ? "started in background" : "moved to background"} as ${details.backgroundTaskId}`;
137 | 	}
138 | 	if (name === "edit") {
139 | 		const stats = diffStats(result.details);
140 | 		if (stats) return stats;
141 | 	}
142 | 	const lineCount = resultTextLines(result).length;
143 | 	if (lineCount === 0) return result.content.some((block) => block.type === "image") ? "image" : "no output";
144 | 	return `${lineCount} ${lineCount === 1 ? "line" : "lines"}`;
145 | }
