1 | /**
2 |  * Shared utility for truncating text to visual lines (accounting for line wrapping).
3 |  * Used by both tool-execution.ts and bash-execution.ts for consistent behavior.
4 |  */
5 | 
6 | import { Text } from "@zykairotis/ice-tui";
7 | 
8 | export interface VisualTruncateResult {
9 | 	/** The visual lines to display */
10 | 	visualLines: string[];
11 | 	/** Number of visual lines that were skipped (hidden) */
12 | 	skippedCount: number;
13 | }
14 | 
15 | /**
16 |  * Truncate text to a maximum number of visual lines (from the end).
17 |  * This accounts for line wrapping based on terminal width.
18 |  *
19 |  * @param text - The text content (may contain newlines)
20 |  * @param maxVisualLines - Maximum number of visual lines to show
21 |  * @param width - Terminal/render width
22 |  * @param paddingX - Horizontal padding for Text component (default 0).
23 |  *                   Use 0 when result will be placed in a Box (Box adds its own padding).
24 |  *                   Use 1 when result will be placed in a plain Container.
25 |  * @returns The truncated visual lines and count of skipped lines
26 |  */
27 | export function truncateToVisualLines(
28 | 	text: string,
29 | 	maxVisualLines: number,
30 | 	width: number,
31 | 	paddingX: number = 0,
32 | ): VisualTruncateResult {
33 | 	if (!text) {
34 | 		return { visualLines: [], skippedCount: 0 };
35 | 	}
36 | 
37 | 	// Create a temporary Text component to render and get visual lines
38 | 	const tempText = new Text(text, paddingX, 0);
39 | 	const allVisualLines = tempText.render(width);
40 | 
41 | 	if (allVisualLines.length <= maxVisualLines) {
42 | 		return { visualLines: allVisualLines, skippedCount: 0 };
43 | 	}
44 | 
45 | 	// Take the last N visual lines
46 | 	const truncatedLines = allVisualLines.slice(-maxVisualLines);
47 | 	const skippedCount = allVisualLines.length - maxVisualLines;
48 | 
49 | 	return { visualLines: truncatedLines, skippedCount };
50 | }
